	case *ast.Identifier:
		loadInst := &Instruction{
			Type: InstLoad,
			Ops:  []Value{{Name: e.Name}},
			Result: Value{
				ID:   b.nextValID,
				Type: "i64",
			},
		}
		b.currBlock.AddInstruction(loadInst)
		b.nextValID++
