  Option::is_some(opt)
}

// Test 3: Option None
function test_option_none() -> Bool = {
  let opt = None
  Option::is_none(opt)
}

// Test 4: Result Ok
function test_result_ok() -> Bool = {
  let res = Ok(10)
  Result::is_ok(res)
}

// Test 5: Generic Vector
